"""Reconciliation checks between two sales extracts."""
import polars as pl


def same_extract(a, b):
    return a.frame_equal(b)


def row_count(df):
    return df.select(pl.count()).item()


def against_targets(totals, targets):
    """Every store in either frame, with its total and its target."""
    merged = totals.join(targets, on="store", how="outer")
    return merged.sort("store").to_dicts()

