"""Store sales reporting on polars: totals, running sums and lookups."""
import polars as pl

REGIONS = {"n1": "north", "n2": "north", "s1": "south"}


def load(rows):
    return pl.DataFrame(rows)


def totals_by_store(df):
    out = df.groupby("store").agg(pl.col("amount").sum().alias("total"))
    return out.sort("store").to_dicts()


def numbered(df):
    """The rows with a 0-based id column in front."""
    return df.with_row_count("row_id").to_dicts()


def running_total(df):
    return df.select(pl.col("amount").cumsum()).to_series().to_list()


def previous_amount(df):
    return df.select(pl.col("amount").shift(periods=1)).to_series().to_list()


def with_tax(df, rate=0.2):
    return df.select(pl.col("amount").apply(lambda v: round(v * (1 + rate), 2))).to_series().to_list()


def region_of(df):
    """Region per row; stores without a region get None."""
    return df.select(pl.col("store").map_dict(REGIONS)).to_series().to_list()

