import pytest

from app import sales

ROWS = {"store": ["n1", "s1", "n1", "w1", "n2"], "amount": [10, 5, 7, 3, 4]}


@pytest.fixture
def df():
    return sales.load(ROWS)


def test_totals_by_store(df):
    assert sales.totals_by_store(df) == [
        {"store": "n1", "total": 17}, {"store": "n2", "total": 4},
        {"store": "s1", "total": 5}, {"store": "w1", "total": 3}]


def test_numbered(df):
    rows = sales.numbered(df)
    assert [r["row_id"] for r in rows] == [0, 1, 2, 3, 4]
    assert rows[3]["store"] == "w1"


def test_running_total(df):
    assert sales.running_total(df) == [10, 15, 22, 25, 29]


def test_previous_amount(df):
    assert sales.previous_amount(df) == [None, 10, 5, 7, 3]


def test_with_tax(df):
    assert sales.with_tax(df) == [12.0, 6.0, 8.4, 3.6, 4.8]


def test_region_of(df):
    assert sales.region_of(df) == ["north", "south", "north", None, "north"]

